const productUrl=root+'products/school-management/';
const uiIcon=(name)=>{const paths={mail:'<rect x="3" y="5" width="18" height="14" rx="3"/><path d="m4 7 8 6 8-6"/>',chat:'<path d="M20 11.5a8 8 0 0 1-8 8 9 9 0 0 1-3-.5L4 21l1.4-4.8A8 8 0 1 1 20 11.5Z"/><path d="M9 8c0 4 2 6 6 6l1-2-2-1-1 1-2-2 1-1-1-2Z"/>',web:'<rect x="3" y="4" width="18" height="16" rx="3"/><path d="M3 9h18M7 6.5h.01M10 6.5h.01m0 6-3 2 3 2m4-4 3 2-3 2"/>',mobile:'<rect x="6" y="2" width="12" height="20" rx="3"/><path d="M10 5h4m-3 14h2"/>',store:'<path d="M4 10v10h16V10M3 10l2-6h14l2 6M3 10c0 3 4 3 4 0 0 3 5 3 5 0 0 3 5 3 5 0 0 3 4 3 4 0M9 20v-6h6v6"/>',system:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.system}</svg>`;};
const cta=()=>`<button class="btn" data-quote>${t('اطلب عرض سعر','Request a tailored quote')} <span aria-hidden="true">${arrow}</span></button>`;
const trialAction=()=>(SITE_CONFIG.products.school.trial.downloadUrl?`<a class="btn" href="#request-trial" data-simple-trial>${t('تنزيل النسخة التجريبية','Download the trial')} <span aria-hidden="true">↓</span></a>`:`<button class="btn" data-demo>${t('احصل على النسخة التجريبية','Get the trial version')}</button>`) + (SITE_CONFIG.products.school.trial.releaseNotesUrl?`<a class="release-link" href="${SITE_CONFIG.products.school.trial.releaseNotesUrl}" target="_blank" rel="noopener noreferrer">${t('الإصدار وملاحظات التحديث','Release & update notes')} <span aria-hidden="true">↗</span></a>`:'') + `<a class="release-link" href="#installation">${t('إرشادات التثبيت','Installation guide')}</a><a class="release-link" href="#download-integrity">${t('بصمة الملف SHA-256','File SHA-256')}</a>`;
const art=()=>`<div class="art" role="img" aria-label="${t('رسم توضيحي لوحدات النظام، وليس لقطة من البرنامج','Illustration of system modules, not a product screenshot')}"><div class="sheet"><div class="sheet-title">${t('إدارة المدرسة','School management')}<span aria-hidden="true">▦</span></div><div class="flow"><div><b aria-hidden="true">◎</b>${t('الطلاب','Students')}</div><div><b aria-hidden="true">▤</b>${t('الرسوم','Fees')}</div><div><b aria-hidden="true">▦</b>${t('الجداول','Timetables')}</div></div><div class="mini-row"><span>${t('الإدارة والمعلمون','Staff & teachers')}</span><span>${t('أولياء الأمور والطلاب','Parents & students')}</span></div></div><div class="art-label">${t('رسم توضيحي للمنتج، وليس صورة من واجهته','Product module illustration — not an actual interface')}</div></div>`;
const productMedia=()=>{const media=SITE_CONFIG.products.school.media;const video=media.video;const shot=media.screenshots[0];const source=typeof shot==='string'?shot:shot?.src;return `<figure class="product-media"><div class="product-media-bar"><span>GOEGSA <b>School Management System</b></span><span aria-hidden="true">···</span></div><div class="product-media-screen">${video?`<video muted autoplay loop playsinline preload="metadata" ${source?`poster="${source}"`:''} aria-label="${t('فيديو توضيحي لنظام إدارة المدارس','School Management System overview video')}"><source src="${typeof video==='string'?video:video.src}"></video>`:source?`<img src="${source}" alt="${t('واجهة نظام إدارة المدارس','School Management System interface')}" loading="lazy">`:art()}</div><figcaption>${source||video?t('اكتشف نظام إدارة المدارس من GOEGSA','Explore GOEGSA School Management System'):t('تصوّر توضيحي لوحدات النظام — ستُضاف صور الواجهة ومقاطع العرض هنا لاحقًا.','System module illustration — interface images and demo clips will be added here.')}</figcaption></figure>`;};
const modules=SITE_CONFIG.products.school.modules;
const heroSlides=[
{image:'hero-school.webp',alt:t('إدارة مدرسية ومعلم يتعاونان باستخدام حاسوب في مكتب مدرسي','A school administrator and teacher collaborating at a laptop'),category:t('نظام إدارة المدارس','School Management System'),title:t('وقت أقل للإجراءات.<br>ومساحة أكبر للتعليم.','Less time on admin.<br>More room for education.'),description:t('اجمع شؤون الطلاب والرسوم والحضور والجداول في نظام واحد، وتعرّف على ما يناسب مدرستك.','Bring student records, fees, attendance and timetables together. Explore what fits your school.'),link:productUrl,action:t('اكتشف نظام المدارس','Explore the school system')},
{image:'hero-commerce.webp',alt:t('صاحب متجر صغير ينظّم طلبًا مع زميلته باستخدام الحاسوب','A small business owner and colleague organizing an order with a laptop'),category:t('المواقع والمتاجر الإلكترونية','Websites & online stores'),title:t('منتجاتك أقرب.<br>وتجربة عميلك أوضح.','Bring your products closer.<br>Make the journey clearer.'),description:t('مواقع ومتاجر تعرض ما تقدّمه بوضوح، وتنظّم رحلة العميل من التعرّف على المنتج إلى طلبه.','Websites and stores that explain your offer and organize the journey from discovery to ordering.'),link:root+'services/',action:t('استكشف خدماتنا','Explore our services')},
{image:'hero-mobile.webp',alt:t('مهنيان يتعاونان على هاتف ذكي في مساحة عمل مضيئة','Two professionals reviewing a smartphone in a bright workspace'),category:t('التطبيقات وأنظمة الإدارة','Applications & management systems'),title:t('خدمات أسهل.<br>ليوم عمل أكثر تنظيمًا.','Simpler services.<br>A more organized workday.'),description:t('نطوّر تطبيقات وأنظمة حول المهام التي تهمك، لتكون المعلومات والخطوات أوضح لمستخدميك.','We develop applications and systems around the tasks that matter, with clearer information and workflows for your users.'),link:root+'contact/',action:t('ناقش مشروعك','Discuss your project')},
{brand:true,duration:SITE_CONFIG.carousel.identityMs,image:'brand-reference.webp',alt:t('تصوّر لهوية GOEGSA بتدرّجات الأخضر والفيروزي','GOEGSA brand concept in green and turquoise'),category:t('هوية GOEGSA','GOEGSA identity'),title:t('تطوير البرمجيات والحلول الرقمية','Software development & digital solutions'),description:t('من احتياج واضح إلى تجربة رقمية تخدم الناس والأعمال.','From a clear need to digital experiences that serve people and businesses.'),link:root+'about/',action:t('تعرّف على GOEGSA','About GOEGSA')}
];
function renderHeroSlide(slide,i){const body=slide.brand?`<div class="hero-brand-content"><span class="hero-category">${slide.category}</span><div class="brand-banner brand-banner-light hero-brand-visual" role="img" aria-label="${slide.alt}"></div><h2>${slide.title}</h2><p class="hero-description">${slide.description}</p><a class="text-link" href="${slide.link}">${slide.action} ${arrow}</a></div>`:`<div class="hero-slide-copy"><p class="hero-category">${slide.category}</p>${i===0?'<h1>':'<h2>'}${slide.title}${i===0?'</h1>':'</h2>'}<p class="hero-description">${slide.description}</p><a class="btn" href="${slide.link}">${slide.action}<span aria-hidden="true">${arrow}</span></a></div><div class="hero-slide-media"><img src="/assets/${slide.image}" srcset="/assets/${slide.image.replace('.webp','-480.webp')} 480w, /assets/${slide.image.replace('.webp','-800.webp')} 800w, /assets/${slide.image} 1536w" sizes="(max-width: 760px) calc(100vw - 40px), (max-width: 1240px) 50vw, 620px" alt="${slide.alt}" width="1536" height="1024" ${i===0?'fetchpriority="high"':'loading="lazy"'} decoding="async"><span class="hero-image-note">${t('صورة توضيحية','Illustrative image')}</span></div>`;return `<article class="hero-slide ${slide.brand?'hero-brand ':''}${i===0?'is-active':''}" dir="${en?'ltr':'rtl'}" role="group" aria-roledescription="slide" aria-label="${i+1} / ${heroSlides.length}" ${i?'inert aria-hidden="true"':''}>${body}</article>`;}
const heroCarousel=`<section class="hero-carousel" aria-label="${t('منتجات GOEGSA وحلولها الرقمية','GOEGSA products and digital solutions')}" aria-roledescription="carousel"><div class="wrap"><div class="carousel-window"><div class="carousel-track" dir="ltr">${heroSlides.map(renderHeroSlide).join('')}</div><button class="carousel-arrow" type="button" data-slide-prev aria-label="${t('الشريحة السابقة','Previous slide')}"><span aria-hidden="true">←</span></button><button class="carousel-arrow" type="button" data-slide-next aria-label="${t('الشريحة التالية','Next slide')}"><span aria-hidden="true">→</span></button></div><div class="carousel-controls"><div class="carousel-nav"><div class="carousel-dots" role="group" aria-label="${t('اختيار الشريحة','Choose slide')}">${heroSlides.map((slide,i)=>`<button type="button" class="carousel-dot ${i===0?'is-active':''}" data-slide="${i}" aria-label="${slide.category}" aria-pressed="${i===0}"><span></span></button>`).join('')}</div></div><p class="carousel-caption">${t('حلول رقمية تبدأ من احتياجات الناس والأعمال.','Digital solutions that start with people and their work.')}</p><button type="button" class="carousel-pause" aria-pressed="false"><span class="pause-icon" aria-hidden="true">Ⅱ</span><span class="pause-label">${t('إيقاف الحركة','Pause motion')}</span></button><span class="sr-only carousel-status" aria-live="polite" aria-atomic="true"></span></div></div></section>`;
const home=heroCarousel+`<section class="feature" id="products"><div class="wrap split"><div><span class="tag">${t('منتجنا الأول','Our first product')}</span><h2>${t('إدارة الطلاب والرسوم<br>واليوم الدراسي في نظام واحد.','Students, fees and the school day.<br>In one system.')}</h2><p>${t('نظام إدارة المدارس من GOEGSA يجمع الوظائف الإدارية والأكاديمية والمالية في واجهة عربية. يُثبّت على جهاز المدرسة وتُستخدم واجهته عبر المتصفح.','GOEGSA School Management System brings administrative, academic and financial functions together in an Arabic interface. Installed at your school and accessed through a browser.')}</p><a class="text-link" href="${productUrl}">${t('تعرّف على النظام','Explore the system')} <span aria-hidden="true">${arrow}</span></a></div>${productMedia()}</div></section><section class="standard" id="services"><div class="wrap"><div class="section-top"><div class="section-head"><h2>${t('من حضورك الرقمي<br>إلى إدارة أعمالك.','From your digital presence<br>to everyday operations.')}</h2></div><p>${t('نحدّد نطاق كل مشروع وفق احتياجه، ونوضّح المخرجات والتكلفة قبل بدء التنفيذ.','Each project starts with a defined scope, deliverables and an agreed cost before development begins.')}</p></div><div class="services">${[['⌘','تطوير المواقع','Website development','مواقع تعريفية تشرح نشاطك وتسهّل وصول العملاء إليك.','Company websites that explain your business and help customers reach you.'],['◫','تطبيقات الجوال','Mobile applications','تطبيقات تراعي تجربة المستخدم واحتياجات مشروعك.','Applications built around your users and project requirements.'],['▧','المتاجر الإلكترونية','Online stores','واجهات لعرض المنتجات وتنظيم تجربة التصفح والطلب.','Storefronts for presenting products and organizing the browsing and ordering experience.'],['▦','أنظمة الإدارة','Management systems','أدوات لتنظيم البيانات والإجراءات ومتابعة العمل.','Tools to organize records, workflows and day-to-day operations.']].map(x=>`<article class="service"><span class="icon" aria-hidden="true">${uiIcon({'⌘':'web','◫':'mobile','▧':'store','▦':'system'}[x[0]])}</span><h3>${t(x[1],x[2])}</h3><p>${t(x[3],x[4])}</p></article>`).join('')}</div></div></section><section class="about" id="about"><div class="wrap"><div class="brand-banner brand-banner-dark" role="img" aria-label="${t('تصوّر بصري لهوية GOEGSA على خلفية داكنة','GOEGSA brand concept on a dark background')}"></div><div class="about-row"><div><h2>${t('نطوّر وفق احتياجاتك.<br>ونبدأ بما يهم عملك.','Built around your needs.<br>Starting with what matters.')}</h2><p>${t('شركة لتطوير البرمجيات والحلول الرقمية، تخاطب الأفراد والشركات الناشئة والمنشآت الصغيرة والمتوسطة.','A software and digital solutions company serving individuals, startups and small and medium-sized businesses.')}</p></div>${cta()}</div><div class="principles"><span>${t('نطاق عمل واضح','Clear project scope')}</span><span>${t('واجهات سهلة الفهم','Understandable interfaces')}</span><span>${t('معلومات تساعدك على الاختيار','Details that support decisions')}</span></div></div></section>`;
const faqs=[['كيف يساعدني النظام في إدارة المدرسة؟','How can the system help my school?','يجمع بيانات الطلاب والرسوم والحضور والجداول والتقارير، ويتيح للمدير والمعلم وولي الأمر متابعة ما يخصه من خلال صلاحيات وبوابات مخصّصة.','It brings student records, fees, attendance, timetables and reports together, with role-based access and dedicated portals for administrators, teachers and parents.'],['أين يعمل النظام وأين تبقى البيانات؟','Where does it run and where is the data stored?','يُثبّت على جهاز ويندوز في المدرسة وتُستخدم واجهته عبر المتصفح. تبقى قاعدة البيانات على جهاز التشغيل، ويمكن إعداد وصول خارجي للبوابات.','It is installed on a Windows computer at your school and accessed through a browser. Data stays on the host computer; external access can be configured for portals.'],['هل أستطيع تجربة النظام قبل اتخاذ القرار؟','Can I try it before deciding?','نعم، تتوفر تجربة مجانية لمدة 14 يومًا لاستكشاف الوظائف المتاحة وتقييم ملاءمتها لمدرستك. يمكنك طلب المساعدة في تحديد المسارات الأهم للتجربة.','Yes. A 14-day free trial lets you explore available features and evaluate suitability for your school. Ask us to help identify the most relevant workflows to try.'],['كيف أحصل على عرض سعر مناسب؟','How do I get a tailored quote?','أخبرنا بعدد الطلاب والفروع والوظائف التي تحتاجها. سنراجع احتياجات المدرسة ونقدّم عرضًا واضحًا بالنطاق المناسب لها.','Tell us your student and branch counts and required features. We will review your needs and prepare a clear proposal with the appropriate scope.'],['هل يوجد تطبيق للجوال؟','Is mobile access available?','تدعم بوابة ولي الأمر الإضافة إلى شاشة الجوال كتطبيق ويب تقدّمي. لا يوجد تطبيق جوال أصلي حاليًا.','The parent portal can be added to a mobile home screen as a progressive web app. A native mobile app is not currently available.']];
const productSections=SITE_CONFIG.products.school;
const portalSection=`<section class="standard" id="portals"><div class="wrap"><div class="section-top"><div><h2>${t('ثلاث بوابات.<br>تجربة أقرب لكل مستخدم.','Three portals.<br>A closer connection for every user.')}</h2></div><p>${t('المعلومات المناسبة للشخص المناسب، ضمن صلاحياته ودوره في المدرسة.','The right information for each person, within their role and permissions.')}</p></div><div class="portal-grid">${productSections.portals.map(x=>`<article class="portal-card"><h3>${t(x[0],x[1])}</h3><p>${t(x[2],x[3])}</p><ul>${x[4].map(f=>`<li>${t(f[0],f[1])}</li>`).join('')}</ul></article>`).join('')}</div></div></section>`;
const integrationsSection=`<section class="feature" id="integrations"><div class="wrap"><div class="section-top"><div><h2>${t('وسّع التجربة.<br>بالتكاملات التي تحتاجها.','Extend the experience.<br>With the connections you need.')}</h2></div><p>${t('اختيارية وتُفعّل بحسابات المدرسة وإعداداتها، مع تحمّلها رسوم الجهات الخارجية.','Optional integrations use the school’s own accounts and settings, with third-party charges paid by the school.')}</p></div><div class="integration-grid">${productSections.integrations.map(x=>`<article class="module"><span class="tag">${t('اختياري','Optional')}</span><h3>${t(x[0],x[1])}</h3><p>${t(x[2],x[3])}</p></article>`).join('')}</div><details class="product-detail"><summary>${t('حالة الفوترة الإلكترونية وزاتكا','E-invoicing and ZATCA status')}</summary><p>${t('الربط غير متاح للاستخدام الفعلي بعد، ولم يُختبر في بيئة زاتكا ولم يحصل على اعتماد منها. لا نعرضه كميزة جاهزة، ولا يدعم حاليًا الفواتير الضريبية القياسية بين المنشآت.','The integration is not ready for production use. It has not been tested in ZATCA’s environment or certified by ZATCA, and is not presented as an available capability. Standard business-to-business tax invoices are not currently supported.')}</p></details></div></section>`;
const protectionSection=`<section class="standard" id="data-controls"><div class="wrap"><h2>${t('صلاحيات أوضح.<br>واستعداد أفضل لحماية العمل.','Clearer access.<br>Better preparation for protecting your work.')}</h2><div class="value-grid">${[['كل دور في نطاقه','Access suited to each role','صلاحيات قابلة للتخصيص، والمعلم يرى الفصول والمواد المسندة إليه.','Customizable permissions; teachers access their assigned classes and subjects.'],['نسخ احتياطي يشمل الملفات','Backups include uploaded files','نسخ يومية تلقائية، ونسخة أمان قبل الاستعادة وترقية قاعدة البيانات.','Automatic daily backups and safety copies before restoration and database upgrades.'],['تحديثات موثّقة المصدر','Source-verified updates','التحديثات موقّعة رقميًا، ويُتحقّق من سلامة ملف التحديث قبل التثبيت.','Digitally signed updates, with integrity verification before installation.']].map(x=>`<article><h3>${t(x[0],x[1])}</h3><p>${t(x[2],x[3])}</p></article>`).join('')}</div><details class="product-detail"><summary>${t('تفاصيل حماية الحسابات والنسخ الاحتياطية','Account and backup protection details')}</summary><p>${t('تُحفظ كلمات المرور كبصمات أحادية الاتجاه، ومفاتيح التكاملات مشفّرة، مع الحد من محاولات الدخول ورموز تحقق محدودة الاستخدام. النسخ الاحتياطية نفسها غير مشفّرة؛ يلزم حفظها في مكان آمن واختبار استعادتها.','Passwords are stored as one-way hashes and integration credentials are encrypted, with login rate limits and limited-use verification codes. Backup files themselves are not encrypted; store them securely and test restoration.')}</p></details></div></section>`;
const installationGuideHtmlEn="<details class=\"install-step\" open><summary>Before you begin</summary><div><ul><li>Use a Windows 10 or 11 computer as the school server. Keep it running during school hours, preferably connected to power and the school network.</li><li>The installation itself does not require an administrator account. The optional firewall and sleep settings request administrator approval once.</li><li>Keep a copy of the installer and download it only through the official link on this website.</li></ul></div></details><details class=\"install-step\"><summary>1) Download</summary><div><p>Download <code>SchoolSystemSetup.exe</code> using the download button. To check that it matches the published file, compare its SHA-256 hash with the hash in the Download verification section for the same release. Open PowerShell and run:</p><pre dir=\"ltr\"><code>(Get-FileHash &quot;$env:USERPROFILE\\Downloads\\SchoolSystemSetup.exe&quot; -Algorithm SHA256).Hash</code></pre></div></details><details class=\"install-step\"><summary>2) Windows launch notice</summary><div><p>Windows may display a notice because the current installer is not signed with an Authenticode certificate. Check the download source, release version and published SHA-256 hash before deciding to run it. A matching hash confirms file consistency; it does not replace a security scan or your school's security policies. Contact support before continuing if you are unsure.</p></div></details><details class=\"install-step\"><summary>3) Installation options</summary><div><p>After selecting the installer language, you will see additional tasks. On the <strong>server computer</strong> that other devices will connect to, select:</p><ul><li>A desktop shortcut, if wanted.</li><li>Start the program automatically when signing in to Windows: recommended for the server.</li><li>Allow the program through Windows Firewall on private networks only: requires administrator approval. Other computers and phones cannot connect without the required firewall access.</li><li>Prevent sleep while connected to power: unchecked by default and recommended for the server; requires administrator approval. Uninstalling restores the original power plan.</li></ul><p>These server options are not needed for an individual trial on one computer.</p></div></details><details class=\"install-step\"><summary>4) First launch</summary><div><ol><li>Read the <strong>software agreement</strong> through the terms link, select the acceptance checkbox and continue.</li><li>On the <strong>first-run setup</strong> page, create the system administrator account and choose a strong password. Store it securely; it cannot be recovered through this website.</li><li>The program includes a <strong>14-day trial</strong> with all features. After purchase, enter the license key on the Licensing page.</li></ol></div></details><details class=\"install-step\"><summary>5) Connect from a phone or another computer</summary><div><ul><li>Connect the device to the <strong>same school network</strong>, by Wi-Fi or cable.</li><li>At startup, the program displays the server address in the form <code>http://server-address:5000</code>. Open that address in the other device's browser.</li><li>On iPhone, open the parent portal in Safari, then choose Share and Add to Home Screen. On Android, use the portal directly in the browser.</li><li>Mobile notifications require a secure HTTPS address configured by the school; they are not available over the ordinary local HTTP address. On iPhone and iPad, Web Push requires iOS or iPadOS 16.4 or later and a web app added to the Home Screen.</li></ul></div></details><details class=\"install-step\"><summary>6) Backups</summary><div><ul><li>After important work, open Settings, then Backup. Create and download a backup, and keep it on an external drive or USB drive.</li><li>Backups are <strong>not encrypted</strong>. Store them securely and do not send them through untrusted channels.</li><li>Installation-specific encryption keys are deliberately excluded from backups. When restoring on a new computer, you may need to re-enter some external service keys, such as WhatsApp or payment service keys.</li></ul></div></details><details class=\"install-step\"><summary>7) Updates</summary><div><p>Open Check for updates in the dashboard. If a newer version is available, the program downloads it after your approval and checks the update signature and hash before installation. Create a backup before every update.</p></div></details><details class=\"install-step\"><summary>8) Uninstall</summary><div><p>Use Windows Settings, then Apps. Create a backup first, because uninstalling may remove the program's local data.</p></div></details><details class=\"install-step\"><summary>9) Help</summary><div><p>Use the support channels listed on this website. Include the program version from About and a description of the issue. Do not send passwords or real student data.</p></div></details>";
const installationGuideHtml="<details class=\"install-step\" open><summary>قبل أن تبدأ</summary><div><ul><li>جهاز يعمل بنظام ويندوز 10 أو 11 يكون «خادم المدرسة»: يُترك مفتوحًا أثناء الدوام، ويفضَّل أن يكون موصولًا بالكهرباء وبشبكة المدرسة.</li><li>لا يحتاج التثبيت إلى حساب مسؤول للتثبيت نفسه، لكن خيارين اختياريين (جدار الحماية ومنع السكون) يطلبان موافقة المسؤول مرة واحدة.</li><li>احتفظ بنسخة المثبّت التي نزّلتها، ولا تنزّله إلا من الرابط الرسمي في هذا الموقع.</li></ul></div></details><details class=\"install-step\"><summary>1) التنزيل</summary><div><p>نزّل الملف <code dir=\"ltr\">SchoolSystemSetup.exe</code> من زر التنزيل. وإن أردت التأكد أنه الملف الأصلي فقارن بصمته (SHA-256) بالبصمة المعروضة في قسم «التحقق من التنزيل» لنفس الإصدار: افتح PowerShell واكتب:</p><pre dir=\"ltr\"><code>(Get-FileHash &quot;$env:USERPROFILE\\Downloads\\SchoolSystemSetup.exe&quot; -Algorithm SHA256).Hash</code></pre></div></details><details class=\"install-step\"><summary>2) تنبيه ويندوز عند التشغيل</summary><div><p>قد يعرض ويندوز تنبيهًا لأن ملف التثبيت الحالي غير موقّع بشهادة Authenticode. تحقق من مصدر التنزيل ورقم الإصدار وبصمة SHA-256 المعروضة قبل اتخاذ قرار التشغيل. تطابق البصمة يؤكد تطابق الملف ولا يغني عن فحصه أو سياسات أمان المدرسة. إذا لم تكن متأكدًا فتواصل مع الدعم قبل المتابعة.</p></div></details><details class=\"install-step\"><summary>3) نافذة التثبيت: اختيار المهام</summary><div><p>بعد اختيار اللغة تظهر خيارات إضافية. على <strong>جهاز الخادم</strong> الذي ستفتحه الأجهزة الأخرى، علّم:</p><ul><li>اختصار على سطح المكتب (اختياري).</li><li>تشغيل البرنامج تلقائيًا عند دخول ويندوز (موصى به للخادم).</li><li>السماح للبرنامج في جدار حماية ويندوز، للشبكات الخاصة فقط (يطلب موافقة المسؤول). بدونه لن تتمكن الأجهزة الأخرى والجوالات من الاتصال.</li><li>منع سكون الجهاز عند التوصيل بالكهرباء (غير معلَّم افتراضيًا، موصى به للخادم، يطلب موافقة المسؤول). وعند إزالة البرنامج يعيد المُزيل خطة الطاقة الأصلية.</li></ul><p>أما إن ثبّت البرنامج على جهاز مكتبي لتجربة فردية فلا حاجة لهذه الخيارات.</p></div></details><details class=\"install-step\"><summary>4) أول تشغيل</summary><div><ol><li>تظهر شاشة <strong>اتفاقية الاستخدام</strong>: اقرأ الشروط عبر رابط «الاطلاع على الشروط والأحكام»، ثم علّم مربع الموافقة واضغط «متابعة».</li><li>تظهر صفحة <strong>إعداد أول تشغيل</strong>: أنشئ حساب مدير النظام واختر كلمة مرور قوية، واحتفظ بها في مكان آمن. لا يمكن استرجاعها من الموقع.</li><li>يعمل البرنامج بنسخة <strong>تجريبية مدتها 14 يومًا</strong> بكامل الميزات. وعند الشراء تستلم مفتاح ترخيص تُدخله من صفحة «الترخيص».</li></ol></div></details><details class=\"install-step\"><summary>5) الدخول من الجوال أو من جهاز آخر</summary><div><ul><li>يجب أن يكون الجهاز على <strong>نفس شبكة المدرسة</strong> (واي فاي أو كابل).</li><li>يعرض البرنامج عند تشغيله عنوان الخادم بصيغة <code dir=\"ltr\">http://عنوان-الجهاز:5000</code>. افتح هذا العنوان في متصفح الجوال.</li><li>على آيفون: لإضافة بوابة ولي الأمر للشاشة الرئيسية افتح العنوان في Safari ثم «مشاركة» ثم «إضافة إلى الشاشة الرئيسية». وعلى أندرويد تعمل من المتصفح مباشرة.</li><li>الإشعارات على الجوال تتطلب عنوانًا آمنًا (https) تهيّئه المدرسة، وليست متاحة على عنوان الشبكة الداخلية العادي. على آيفون وآيباد، تتطلب إشعارات الويب iOS أو iPadOS 16.4 أو أحدث، وإضافة التطبيق إلى الشاشة الرئيسية.</li></ul></div></details><details class=\"install-step\"><summary>6) النسخ الاحتياطي (مهم)</summary><div><ul><li>من «الإعدادات» ثم «النسخ الاحتياطي» أنشئ نسخة بعد أي عمل مهم، وحمّلها واحفظها على قرص خارجي أو فلاش.</li><li>النسخ الاحتياطية <strong>غير مشفّرة</strong>، فاحفظها في مكان آمن ولا ترسلها عبر وسائل غير موثوقة.</li><li>مفاتيح التثبيت الخاصة بالتشفير لا تسافر مع النسخة عمدًا؛ لذلك عند الاستعادة على جهاز جديد قد تحتاج لإعادة إدخال بعض مفاتيح الخدمات الخارجية (مثل الواتساب أو الدفع).</li></ul></div></details><details class=\"install-step\"><summary>7) التحديث</summary><div><p>من لوحة التحكم افتح «التحقق من التحديثات». إن وُجد إصدار أحدث فسيُنزَّل بعد موافقتك ويُتحقق من توقيعه وبصمته قبل التثبيت. خذ نسخة احتياطية قبل أي تحديث.</p></div></details><details class=\"install-step\"><summary>8) الإزالة</summary><div><p>من إعدادات ويندوز ثم «التطبيقات». قبل الإزالة خذ نسخة احتياطية، فقد تُحذف بيانات البرنامج المحلية مع الإزالة.</p></div></details><details class=\"install-step\"><summary>9) المساعدة</summary><div><p>للدعم تواصل عبر قنوات الدعم المعلنة في هذا الموقع، وأرفق رقم إصدار البرنامج (يظهر في «حول البرنامج») ووصفًا لما حدث. لا ترسل كلمات مرور ولا بيانات طلاب حقيقية.</p></div></details>";
const installationGuide=`<section id="installation" class="standard installation-guide"><div class="wrap"><div class="section-top"><div><span class="tag">${t('ابدأ بثقة','Getting started')}</span><h2>${t('إرشادات التثبيت والتشغيل','Installation & setup guide')}</h2></div><div><p>${t('من التنزيل إلى أول تشغيل، اتبع الخطوات المناسبة لجهاز المدرسة.','Follow the setup steps from download to first launch on your school computer.')}</p><a class="text-link" href="${!en?'/assets/SchoolSystem-README.md':'/assets/SchoolSystem-README.en.md'}" download>${t('تنزيل دليل التثبيت (README)','Download installation guide (README)')} ↓</a></div></div><div class="installation-content" lang="${en?'en':'ar'}" dir="${!en?'rtl':'ltr'}">${!en?installationGuideHtml:installationGuideHtmlEn}</div><p class="install-support"><a class="text-link" href="${root}contact/">${t('تحتاج مساعدة؟ تواصل مع الدعم','Need help? Contact support')} ${arrow}</a></p></div></section>`;
const productTree=`<section class="product-tree" id="product-map" aria-labelledby="tree-title"><div class="tree-heading"><div><span class="tag">${t('الصورة الكاملة','The complete picture')}</span><h2 id="tree-title">${t('تعرّف على النظام في نظرة واحدة.','Explore the system at a glance.')}</h2><p>${t('الأقسام الرئيسية وفروعها وخدماتها، مع بوابات المستخدمين والتكاملات الاختيارية.','Main modules, functional groups and capabilities, with user portals and optional integrations. The diagram is in Arabic.')}</p></div><a class="text-link" href="/assets/school-system-tree.webp" target="_blank" rel="noopener noreferrer">${t('فتح الصورة بالحجم الكامل','Open full-size image')} ↗</a></div><figure class="tree-figure"><div class="tree-scroll" tabindex="0" role="region" aria-label="${t('شجرة وظائف النظام؛ مرّر أفقيًا على الشاشات الصغيرة لقراءة التفاصيل','System capability tree; scroll horizontally on smaller screens to read details')}"><a href="/assets/school-system-tree.webp" target="_blank" rel="noopener noreferrer" aria-label="${t('فتح شجرة النظام بالحجم الكامل','Open the full-size system tree')}"><img src="/assets/school-system-tree.webp" width="1536" height="1024" loading="lazy" decoding="async" alt="${t('شجرة نظام إدارة المدارس: شؤون الطلاب، الرسوم والتحصيل، المحاسبة، الموظفون والرواتب، النقل المدرسي، خدمات المدرسة، التقارير والإدارة. تتفرع منها الخدمات، مع بوابات ولي الأمر والمعلم والطالب والتكاملات الاختيارية.','School Management System capability tree: student affairs, fees and collections, accounting, staff and payroll, school transport, school services, reports, and administration, plus parent, teacher and student portals and optional integrations.')}"></a></div><figcaption>${t('على الجوال: مرّر الصورة أفقيًا لقراءة التفاصيل، أو افتحها بالحجم الكامل للتكبير. تجد شرح الخدمات نصيًا في الأقسام التالية.','On mobile: scroll the image horizontally, or open it full-size to zoom. Written feature descriptions follow below.')}</figcaption></figure></section>`;
const shieldIcon=`<svg viewBox="0 0 48 48" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="m24 4 16 6v12c0 10-7 17-16 22C15 39 8 32 8 22V10Z"/><path d="m16 24 5 5 11-12"/></svg>`;
const privacyVisual=`<figure class="privacy-visual" aria-labelledby="privacy-visual-title"><div class="privacy-topline"><span class="privacy-indicator" aria-hidden="true"></span>${t('تشغيل محلي داخل المدرسة','Local deployment at school')}<span class="privacy-chip">Windows 10 / 11</span></div><div class="privacy-core"><div class="privacy-shield">${shieldIcon}</div><p id="privacy-visual-title">${t('بيانات المدرسة.<br><strong>على جهاز المدرسة.</strong>','School data.<br><strong>On your school computer.</strong>')}</p><span>${t('قاعدة بيانات محلية • استخدام عبر المتصفح','Local database • Browser access')}</span></div><div class="privacy-connections" aria-hidden="true"><span></span><span></span><span></span></div><ul class="privacy-nodes"><li>${uiIcon('system')}<span>${t('الإدارة','Administration')}</span></li><li>${uiIcon('web')}<span>${t('المعلمون','Teachers')}</span></li><li>${uiIcon('mobile')}<span>${t('البوابات','Portals')}</span></li></ul><div class="privacy-controls"><span>${t('صلاحيات حسب الدور','Role-based access')}</span><span>${t('نسخ احتياطي محلي','Local backups')}</span></div><figcaption>${t('رسم توضيحي لطريقة التشغيل. الاتصال بالخدمات الخارجية والوصول إلى البوابات يعتمدان على إعدادات المدرسة والتكاملات التي تفعّلها.','Deployment illustration. External services and portal access depend on the school’s configuration and enabled integrations.')}</figcaption></figure>`;
const productHero=`<section class="product-hero conversion-hero"><div class="wrap split"><div class="conversion-copy"><span class="product-name">${t('نظام إدارة المدارس من GOEGSA','GOEGSA School Management System')}</span><h1>${t('إدارة مدرستك أبسط.<br>وبياناتها عندك.','Simpler school management.<br>Your data stays with you.')}</h1><p class="intro">${t('اجمع الطلاب والرسوم والجداول والتقارير في نظام واحد يُثبّت على جهاز المدرسة. امنح فريقك وصولًا حسب دوره، وابدأ بتجربة مجانية لمدة 14 يومًا.','Bring students, fees, timetables and reports into one system installed on your school computer. Give your team role-based access and start with a free 14-day trial.')}</p><div class="hero-trust"><span>${shieldIcon}${t('قاعدة البيانات على جهاز المدرسة','Database on your school computer')}</span><span>${t('واجهة عربية • تشغيل عبر المتصفح','Arabic-first • Browser access')}</span></div><div class="conversion-actions"><a class="btn trial-primary" href="#request-trial" data-simple-trial>${t('حمّل النسخة التجريبية مجانًا','Download your free trial')}<span aria-hidden="true">↓</span></a><a class="hero-secondary" href="#installation">${t('كيف أثبّت النظام؟','How do I install it?')} ${arrow}</a></div><p class="download-meta">${t('لويندوز 10 و11 • تجربة 14 يومًا • التنزيل بعد تعبئة بيانات التواصل','Windows 10 & 11 • 14-day trial • Download after completing your contact details')}</p><div class="hero-helper-links"><a href="#download-integrity">${t('الإصدار والتحقق من ملف التنزيل','Release & installer verification')} ↗</a><button type="button" data-quote>${t('تحتاج عرضًا لمدرستك؟','Need a proposal for your school?')}</button></div></div>${privacyVisual}</div></section>`;
const escapeQuote=value=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const approvedTestimonials=(SITE_CONFIG.products.school.testimonials?.items||[]).filter(x=>x.approved===true&&x.quote?.ar&&x.quote?.en&&x.name);
const testimonialSection=`<section class="standard testimonials-section" id="testimonials" aria-labelledby="testimonials-title"><div class="wrap"><div class="section-top"><div><span class="tag">${t('تجارب الاستخدام','User experiences')}</span><h2 id="testimonials-title">${t('آراء العملاء','What customers say')}</h2></div><p>${t('تجربة المدارس مع النظام، بكلمات أصحابها.','Schools’ experiences with the system, in their own words.')}</p></div>${approvedTestimonials.length?`<div class="testimonials-grid">${approvedTestimonials.map(x=>`<figure class="testimonial-card"><span class="testimonial-quote-mark" aria-hidden="true">“</span><blockquote><p>${escapeQuote(en?x.quote.en:x.quote.ar)}</p></blockquote><figcaption><strong>${escapeQuote(x.name)}</strong>${x.organization?`<span>${escapeQuote(x.organization)}</span>`:''}</figcaption></figure>`).join('')}</div>`:`<div class="testimonial-invitation"><div class="testimonial-symbol" aria-hidden="true">${uiIcon('chat')}</div><div><h3>${t('جرّبت النظام؟ شاركنا تجربتك.','Tried the system? Share your experience.')}</h3><p>${t('لم تُنشر آراء عملاء بعد. نرحّب بملاحظاتك حول ما ساعدك في إدارة المدرسة وما ترغب في تحسينه. لا ننشر اسمك أو رأيك إلا بموافقتك.','No customer testimonials have been published yet. Tell us what helped your school and what could be improved. Your name and feedback are published only with your permission.')}</p></div><a class="text-link" href="mailto:support@goegsa.com?subject=${encodeURIComponent(t('تجربتي مع نظام إدارة المدارس','My School Management System experience'))}">${t('شارك تجربتك','Share your experience')} ${arrow}</a></div>`}</div></section>`;
const downloadIntegrity='<section class="download-integrity" id="download-integrity" aria-labelledby="download-integrity-title"><div class="wrap"><span class="tag">'+t('قبل التنزيل','Before downloading')+'</span><h2 id="download-integrity-title">'+t('تحقق من نسخة البرنامج.','Verify your installer.')+'</h2><p>'+t('الإصدار المتاح هنا: ','Available version: ')+'<strong>'+SITE_CONFIG.products.school.trial.version+'</strong> · SchoolSystemSetup.exe</p><p class="checksum-label">SHA-256</p><code class="installer-checksum" dir="ltr">'+SITE_CONFIG.products.school.trial.sha256+'</code><p class="checksum-note">'+t('فُحصت البصمة في 27 أكتوبر 2026 وطابقت بيانات GitHub. البصمة تخص هذا الإصدار تحديدًا.','Verified on 27 October 2026 against GitHub metadata. This checksum applies to this specific release.')+'</p><details><summary>'+t('ماذا يعني التحقق؟','What does verification mean?')+'</summary><p>'+t('ملف التثبيت لهذا الإصدار غير موقّع بشهادة Authenticode. تطابق البصمة يتحقق من تطابق الملف، ولا يثبت خلوه من المشكلات أو يغني عن سياسات أمان المدرسة.','This release installer is not Authenticode-signed. A matching checksum confirms the file matches, not that it is free of issues or exempt from school security policies.')+'</p></details><a class="text-link" href="'+SITE_CONFIG.products.school.trial.releaseNotesUrl+'" target="_blank" rel="noopener noreferrer">'+t('صفحة هذا الإصدار على GitHub','This release on GitHub')+' ↗</a></div></section>';
const productPage=`<div class="wrap breadcrumb"><a href="${root}">${t('الرئيسية','Home')}</a> / ${t('نظام إدارة المدارس','School Management System')}</div>${productHero}${downloadIntegrity}<nav class="product-index" aria-label="${t('أقسام المنتج','Product sections')}"><div class="wrap">${[['product-map','خريطة النظام','System map'],['features','وظائف النظام','Capabilities'],['portals','بوابات المستخدمين','User portals'],['integrations','التكاملات','Integrations'],['data-controls','البيانات والحماية','Data & access'],['testimonials','آراء العملاء','Testimonials'],['installation','التثبيت','Setup'],['trial','تجربة النظام','Try the system']].map(x=>`<a href="#${x[0]}">${t(x[1],x[2])}</a>`).join('')}</div></nav>${productTree}<section class="value-section"><div class="wrap value-grid">${[['إدارة ترى الصورة كاملة','A clearer management view','تابع السجلات والمستحقات والتقارير في بيئة واحدة، بدل التنقل بين ملفات متفرقة.','Review records, outstanding fees and reports in one environment instead of separate files.'],['فريق يعرف خطوته التالية','A team that knows the next step','نظّم الحضور والجداول والمهام اليومية، وحدّد ما يمكن لكل مستخدم الوصول إليه.','Organize attendance, timetables and daily tasks, with access defined for each user.'],['متابعة أقرب لأولياء الأمور','Closer parent engagement','بوابة تتيح متابعة الدرجات والمستحقات والمعلومات المرتبطة بالأبناء.','A dedicated portal for grades, outstanding fees and information relating to children.']].map(x=>`<article><h2>${t(x[0],x[1])}</h2><p>${t(x[2],x[3])}</p></article>`).join('')}</div></section><section class="feature" id="features"><div class="wrap"><div class="section-top"><div><h2>${t('تعرّف على ما يستطيع<br>النظام تقديمه لمدرستك.','Discover what the system<br>can do for your school.')}</h2></div><p>${t('اختر الوظائف التي تخدم طريقة عملك. نحدّد معك النطاق المناسب بعد فهم احتياجات المدرسة.','Choose the capabilities that fit your workflow. We define the appropriate scope after understanding your school’s needs.')}</p></div><div class="modules">${modules.map((x,i)=>`<article class="module"><span class="module-number" aria-hidden="true">${String(i+1).padStart(2,'0')}</span><div class="module-body"><h3>${t(x[0],x[1])}</h3><p>${t(x[2],x[3])}</p><details class="module-detail"><summary>${t('استكشف التفاصيل','Explore details')}</summary><ul>${productSections.moduleDetails[i].map(f=>`<li>${t(f[0],f[1])}</li>`).join('')}</ul></details></div></article>`).join('')}</div></div></section>${portalSection}${integrationsSection}${protectionSection}${testimonialSection}${installationGuide}<section class="standard"><div class="wrap split"><div><h2>${t('تجربة متصلة.<br>لكل من يصنع اليوم الدراسي.','A connected experience.<br>For the people behind the school day.')}</h2><p>${t('المدير يحتاج رؤية واضحة، والمحاسب يحتاج متابعة منظمة، والمعلم يحتاج أدوات تخص فصوله. يجمع النظام هذه المسارات مع بوابات للمعلمين وأولياء الأمور والطلاب حسب الوظائف المتاحة.','Administrators need visibility, accountants need organized records, and teachers need tools for their classes. The system brings these workflows together with teacher, parent and student portals according to available features.')}</p><a class="text-link" href="#trial">${t('اكتشف التجربة بنفسك','Explore the experience yourself')} ${arrow}</a></div><div class="journey-panel"><h3>${t('من أول تسجيل إلى المتابعة اليومية','From enrollment to daily follow-up')}</h3><ol><li>${t('سجّل الطلاب واربط بياناتهم بأولياء الأمور.','Enroll students and link parent records.')}</li><li>${t('نظّم الحضور والجداول والعمل الأكاديمي.','Organize attendance, timetables and academic work.')}</li><li>${t('تابع الدفعات والمستحقات والتقارير.','Track payments, outstanding fees and reports.')}</li><li>${t('امنح كل مستخدم الوصول المناسب لدوره.','Give each user access suited to their role.')}</li></ol></div></div></section><section class="standard" style="padding-top:0"><div class="wrap faq"><h2>${t('أسئلة تساعدك على الاختيار','Questions to help you decide')}</h2>${faqs.map(x=>`<details><summary>${t(x[0],x[1])}</summary><p>${t(x[2],x[3])}</p></details>`).join('')}</div></section><section class="cta" id="trial"><div class="wrap about-row"><div><h2>${t('جرّبه أولًا.<br>ثم اختر ما يناسب مدرستك.','Try it first.<br>Then choose what fits your school.')}</h2><p>${t('استكشف النظام، وشاركنا احتياجاتك للحصول على عرض سعر مصمّم لها.','Explore the system, then share your requirements for a proposal tailored to your school.')}</p></div><div class="actions">${trialAction()}${cta()}</div></div></section>`;
const pageIntro=(label,title,description)=>`<section class="page-intro"><div class="wrap"><nav class="page-location" aria-label="${t('مسار الصفحة','Breadcrumb')}"><a href="${root}">${t('الرئيسية','Home')}</a><span aria-hidden="true">/</span><span aria-current="page">${label}</span></nav><div class="page-intro-grid"><h1>${title}</h1><div class="intro-summary"><p class="intro">${description}</p></div></div></div></section>`;
