const legalPage=kind=>{const content=SITE_CONFIG.legal[kind][en?'en':'ar'];return pageIntro(escapeQuote(content.title),escapeQuote(content.title),escapeQuote(content.intro))+'<section class="legal-content"><div class="wrap">'+content.sections.map(([title,body])=>'<article><h2>'+escapeQuote(title)+'</h2><p>'+escapeQuote(body)+'</p></article>').join('')+'<p><a href="mailto:'+SITE_CONFIG.company.privacyEmail+'">'+SITE_CONFIG.company.privacyEmail+'</a></p></div></section>';};
